pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter: an arbitrary address that will be used as the initializer (owner)
    function testFuzz_property(address potentialOwner) public {
        // keep wide: require non-zero to be meaningful (we still allow zero to show mutant fails)
        // but do not overconstrain — allow zero too as admissible input

        // Prepare caller as potentialOwner
        vm.prank(potentialOwner);
        // call initialize with some typical args; credChainId and credId can be arbitrary
        c.initialize(12345, 67890, "verif", potentialOwner);

        // General rule: after initialize(...) called by potentialOwner, owner() must return potentialOwner
        // The reference satisfies this for every input; the mutant (which returns address(0)) will fail

