pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the initializer caller (actor) so the fuzzer can find differences
    function testFuzz_property(address actor) public {
        // admissible domain: non-zero actor so initialization can validly set owner (Ownable.__Ownable_init rejects zero)
        vm.assume(actor != address(0));

        // fund the actor so they can call initialize if needed (initialize is non-payable here but safe)
        vm.deal(actor, 1 ether);

        // perform initialize as the fuzzed actor
        vm.prank(actor);
        c.initialize(1, 2, "vtype", address(0x1234));

        // query owner via try/catch to be robust (owner() is a view and should not revert)
        bool ok;
        address observed;
        try c.owner() returns (address o) {
            ok = true;
            observed = o;
        } catch {
            ok = false;
            observed = address(0);
        }

        // The single assertion: reference C always returns the initializing actor as owner (ok==true && observed==actor).
        // The mutant that returns address(0) will make this assertion fail for some actor (i.e. most actors),
        // causing the test to fail on the buggy version.
        assertTrue(ok && observed == actor);
    }
}

