pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzzed parameter: an address that will act as the caller of owner().
    // The general rule: reference returns stored owner regardless of caller; mutant returns caller.
    function testFuzz_property(address caller) public {
        // keep wide domain but exclude zero address to ensure meaningful pranks
        vm.assume(caller != address(0));

        // initialize contract as deployer (this test contract) by calling initialize via prank as required by initializer
        // The initializer in C expects msg.sender to be the factory; we can call initialize directly from this test contract
        // which is allowed. Use prereq values.
        uint256 credChainId = 1;
        uint256 credId = 2;
        string memory verificationType = "v";
        address protocolFeeDestination = address(0x1234);

        // call initialize as this test contract (msg.sender == address(this))
        c.initialize(credChainId, credId, verificationType, protocolFeeDestination);

        // After initialize, the stored owner should be address(this)
        address storedOwner = c.owner();

        // Now query owner() from a different caller (fuzzed 'caller').
        // Use vm.prank to make the call originate from 'caller'.
        address ownerFromCaller;
        vm.prank(caller);
        ownerFromCaller = c.owner();

        // The universal property: the reference returns the stored owner regardless of who calls;
        // the mutant that returns msg.sender will return 'caller' when called by caller, which differs
        // whenever caller != storedOwner. We assert that ownerFromCaller equals storedOwner.
        assertTrue(ownerFromCaller == storedOwner);
    }
}

