import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz the caller address (adversarial actor). The stored owner will be set by initialize called from the test.
    function testFuzz_property(address caller) public {
        // Keep caller within valid non-zero addresses to make the test meaningful
        vm.assume(caller != address(0));

        // initialize the contract from a chosen deployer (this sets the stored owner to deployer)
        address deployer = address(this);
        // initialize must be called by the factory in the real contract; here we call initialize directly as test account
        c.initialize(1, 2, "vt", address(0));

        // The general rule: c.owner() must always return the stored owner (the deployer) for any caller who queries it.
        // We will call owner() as the fuzzed caller and observe the returned value using a low-level call (to set msg.sender).

        // perform the call as the fuzzed caller
        vm.prank(caller);
        address reportedOwner = c.owner();

        // The reference C: owner() should always equal the stored owner (the deployer initialized above),
        // i.e., reportedOwner == deployer for ALL callers. The mutant returns msg.sender, so for some caller != deployer
        // the mutant will produce reportedOwner == caller and the assertion will fail.

        assertTrue(reportedOwner == deployer);
    }
}

