import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameter is an arbitrary caller address
    function testFuzz_property(address caller) public {
        // admissible domain: caller must be different from zero (owner in reference is set to msg.sender during initialize which is the test contract by vm), and avoid the test contract itself to allow difference
        vm.assume(caller != address(0));

        // initialize contract as the test contract (setUp used constructor only, we must call initialize)
        // initialization must be called by an address that will become the stored owner; use address(this)
        c.initialize({
            credChainId_: 1,
            credId_: 1,
            verificationType_: "v",
            protocolFeeDestination_: address(0)
        });

        // After initialize, the stored owner should be address(this)
        address storedOwner = c.owner();

        // sanity: storedOwner should equal address(this) for the reference implementation
        // (we keep this as part of admissible domain: only proceed when storedOwner == address(this))
        vm.assume(storedOwner == address(this));

        // Now call owner() as an arbitrary caller via vm.prank to simulate different callers
        bool ok;
        vm.prank(caller);
        try c.owner() returns (address ret) {
            ok = true;
            // if both complete, check that returned owner equals storedOwner
            // For the reference contract this should hold for every caller; mutant will return caller for some caller != storedOwner
            assertTrue(ret == storedOwner);
            return;
        } catch {
            // owner() is view and should not revert in reference; require it doesn't revert
            ok = false;
        }

        // single assertion required: owner's call must succeed (ok == true) and returned value must equal storedOwner
        assertTrue(ok);
    }
}

