pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the actor who will call pause/unpause (owner must call initialize then owner will be deployer)
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a sensible EOA for fuzzing
        vm.assume(caller != address(0));

        // initialize the contract as the deployer (setUp deploys c by this test contract)
        // The initializer expects msg.sender to be the factory; we call initialize from this test contract (msg.sender == address(this))
        // Provide some wide values
        uint256 credChainId = block.chainid;
        uint256 credId = 1;
        string memory vType = "v";
        address protocolFeeDestination = address(0x123);

        // call initialize as this contract
        c.initialize(credChainId, credId, vType, protocolFeeDestination);

        // After initialization, owner() is this contract. We need to test paused() return matches stored flag across transitions.
        // The general property: paused() returns the same boolean as the internal stored paused flag.
        // We can exercise both whenNotPaused (default) and after pausing.

        // 1) Initially paused() should be false (contract unpaused by __Pausable_init)
        bool okInit;
        try c.paused() returns (bool p) { okInit = (p == false); } catch { okInit = false; }
        // now pause via onlyOwner. owner is this contract, so call pause()
        c.pause();

        // 2) After pause, paused() should be true
        bool okPaused;
        try c.paused() returns (bool p2) { okPaused = (p2 == true); } catch { okPaused = false; }

        // 3) Unpause and check again
        c.unPause();
        bool okUnpaused;
        try c.paused() returns (bool p3) { okUnpaused = (p3 == false); } catch { okUnpaused = false; }

        // The single assertion: all observed returns matched the expected stored semantics in the reference implementation.
        // This will fail on the mutant which negates the returned value for some of these checks.
        assertTrue(okInit && okPaused && okUnpaused);
    }
}
